  function load(){try{const raw=localStorage.getItem(STORAGE_KEY);if(raw)state={...clone(defaultState),...JSON.parse(raw)};state.frontier=Math.max(Number(state.frontier)||0,screenToStep[state.screen]||0)}catch(_){}}
  function save(){
    let persisted=true;
    try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}catch(_){persisted=false}
    try{syncMission()}catch(_){}
    const p=$('#saveState');
    if(p){p.textContent=persisted?'Dossier sauvegardé':'Progression active';p.classList.toggle('saved-flash',persisted);if(persisted)setTimeout(()=>p.classList.remove('saved-flash'),220)}
    // UI progression must never depend on browser storage being available.
    setTimeout(()=>{try{syncCompletionUI();renderWorkflowStatuses()}catch(_){}},0)
  }
  function toast(msg){const t=$('#toast');if(!t)return;t.textContent=msg;t.hidden=false;setTimeout(()=>t.hidden=true,2300)}
  function needLabel(id){if(!id)return '';if(id.startsWith('custom:'))return id.slice(7);return needDefs.find(x=>x[0]===id)?.[2]||id}
  function sourceName(id){return strategyDefs.find(x=>x[0]===id)?.[1]||id}
  function missionObservation(){const claims=state.strategyV1?.claims||state.strategyClaims||{};const v1=(state.strategyV1?.sources||state.strategy||[]).map(id=>({id,label:sourceName(id),role:labelFrom(roleOptions,claims[id]?.role),limit:labelFrom(limitOptions,claims[id]?.limit)}));const v2=(state.strategyV2||[]).map(id=>({id,label:sourceName(id)}));return {schemaVersion:2,episode:1,title:'Observer un environnement',status:state.completed?'completed':(state.frontier>0||state.teamName.trim()?'in-progress':'not-started'),updatedAt:new Date().toISOString(),priorities:state.ranks.filter(Boolean).map(id=>({id,label:needLabel(id),decisionLens:labelFrom(needImpactOptions,state.priorityImpacts[id])})),customNeeds:[...state.customNeeds],decisionRequirements:decisionDefs.map(d=>({id:d.id,decision:d.title,selected:[...(state.decisions[d.id]||[])].map(x=>d.options.find(o=>o[0]===x)?.[1]||x)})),observationChain:{generic:[...state.chain],flood:state.floodChain.map(id=>floodChainDefs.find(x=>x[0]===id)?.[1]||id)},sources:{selected:[...state.sources],profiles:clone(state.sourceProfiles),forestPair:[...state.forestPair],forestComplement:labelFrom(complementOptions,state.forestComplement)},context:{metadata:state.metadata.map(id=>labelFrom(metadataDefs,id)),timeMatch:clone(state.timeMatch),comparisonReasons:state.comparisonReasons.map(id=>labelFrom(comparisonReasonDefs,id)),spatioTemporal:clone(state.observationCases)},quality:{diagnostics:clone(state.quality),usage:clone(state.qualityUsage),bridgePriority:[...state.bridgeQuality],mismatch:clone(state.qualityMismatch)},strategy:{v1:state.strategyV1?{frozenAt:state.strategyV1.at,sources:v1,blindSpot:labelFrom(blindSpotOptions,state.strategyV1.blindSpot)}:null,v2:state.strategyV2?{sources:v2,incident:incidentDefs.find(x=>x[0]===state.incident)?.[1]||'',revision:{hypothesis:labelFrom(revisionHypotheses,state.revisionCausal.hypothesis),information:labelFrom(revisionInfoOptions,state.revisionCausal.information),action:labelFrom(revisionActions,state.revisionCausal.action),weakness:labelFrom(revisionWeaknesses,state.revisionCausal.weakness),note:state.revisionNote||''}}:null}}}
  function syncMission(){if(!MissionStore)return;MissionStore.update(d=>{d.team={...(d.team||{}),name:state.teamName||''};d.observation=missionObservation();d.progress=d.progress||{lastEpisodeTouched:0,lastEpisodeCompleted:0,episodes:{}};d.progress.episodes=d.progress.episodes||{};d.progress.episodes['1']={status:d.observation.status,frontier:state.frontier,completed:state.completed,updatedAt:d.observation.updatedAt};d.progress.lastEpisodeTouched=Math.max(Number(d.progress.lastEpisodeTouched)||0,1);if(state.completed)d.progress.lastEpisodeCompleted=Math.max(Number(d.progress.lastEpisodeCompleted)||0,1);return d})}

  function renderStepper(){const viewed=screenToStep[state.screen]||0;$('#stepper').innerHTML=stepLabels.map((l,i)=>`<button class="step-dot ${i<=state.frontier?'':'locked'} ${i<state.frontier?'done':''} ${i===viewed?'active':''}" ${i<=state.frontier?'':'disabled'} data-step="${entryScreens[i]}"><span>${i<state.frontier?'✓':i+1}</span><small>${l}</small></button>`).join('');$$('[data-step]').forEach(b=>b.onclick=()=>showScreen(+b.dataset.step))}
