    const claimsDone=state.strategy.filter(id=>state.strategyClaims[id]?.role&&state.strategyClaims[id]?.limit).length; setWorkflowStatus('strategyClaimsStatus',`${claimsDone} / ${state.strategy.length||2} source(s) qualifiée(s)`,state.strategy.length>=2&&claimsDone===state.strategy.length);
