  function renderDecisions(){const h=$('#decisionCases');if(!h)return;h.innerHTML=decisionDefs.map(d=>{const s=state.decisions[d.id]||[];return `<article class="decision-case"><div class="decision-head"><span>${decisionTagLabels[d.id]||d.id.toUpperCase()}</span><strong>${d.title}</strong><small>${s.length}/${d.limit} retenues</small></div><div class="decision-options">${d.options.map(([id,l])=>{const active=s.includes(id);return `<button data-decision="${d.id}" data-info="${id}" class="${active?'active':''}"><span>${l}</span><b class="option-action">${active?'RETENUE ✓':'RETENIR +'}</b></button>`}).join('')}</div><div class="decision-rule">Maximum ${d.limit}. Laissez de côté ce qui ne change pas la décision immédiate.</div></article>`}).join('');h.querySelectorAll('[data-decision]').forEach(b=>b.onclick=()=>{const d=decisionDefs.find(x=>x.id===b.dataset.decision),arr=[...(state.decisions[d.id]||[])],id=b.dataset.info;if(arr.includes(id))state.decisions[d.id]=arr.filter(x=>x!==id);else if(arr.length<d.limit)state.decisions[d.id]=[...arr,id];else return toast(`Maximum ${d.limit} informations pour ce cas.`);save();renderDecisions();renderSnapshots()});renderDecisionChallenge()}
